CREATE TABLE public.farmer_records (owner_id uuid NOT NULL, kind text NOT NULL CHECK (kind IN ('plan','alert')), id text NOT NULL, payload jsonb NOT NULL CHECK (jsonb_typeof(payload)='object'), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,kind,id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.farmer_records TO authenticated;
GRANT ALL ON public.farmer_records TO service_role;
ALTER TABLE public.farmer_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY farmer_records_own_read ON public.farmer_records FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY farmer_records_own_insert ON public.farmer_records FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY farmer_records_own_update ON public.farmer_records FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE POLICY farmer_records_own_delete ON public.farmer_records FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE INDEX farmer_records_kind_owner ON public.farmer_records(kind,owner_id);
CREATE TABLE public.ingestion_leases (source text PRIMARY KEY, lease_id uuid NOT NULL, expires_at timestamptz NOT NULL);
GRANT ALL ON public.ingestion_leases TO service_role;
ALTER TABLE public.ingestion_leases ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.acquire_ingestion_lease(p_source text,p_lease_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE acquired boolean; BEGIN INSERT INTO public.ingestion_leases(source,lease_id,expires_at) VALUES(p_source,p_lease_id,now()+interval '20 minutes') ON CONFLICT(source) DO UPDATE SET lease_id=excluded.lease_id,expires_at=excluded.expires_at WHERE ingestion_leases.expires_at<now(); GET DIAGNOSTICS acquired=ROW_COUNT; RETURN acquired; END; $$;
REVOKE ALL ON FUNCTION public.acquire_ingestion_lease(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.acquire_ingestion_lease(text,uuid) TO service_role;
CREATE FUNCTION public.release_ingestion_lease(p_source text,p_lease_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ DELETE FROM public.ingestion_leases WHERE source=p_source AND lease_id=p_lease_id $$;
REVOKE ALL ON FUNCTION public.release_ingestion_lease(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.release_ingestion_lease(text,uuid) TO service_role;
ALTER TABLE public.agri_source_runs ADD COLUMN duplicates integer NOT NULL DEFAULT 0;
ALTER TABLE public.agri_source_runs ADD COLUMN corrected integer NOT NULL DEFAULT 0;
COMMENT ON TABLE public.farmer_records IS 'Private validated plans and price alerts; guests remain browser-only. No browser records automatically assigned to an account.';
COMMENT ON TABLE public.ingestion_leases IS 'Service-role-only bounded daily ingestion lease; protects concurrent scheduled/manual callbacks.';